namespace MacroExecute
{
    internal sealed class TestHotkeyRegistrar : IHotkeyRegistrar
    {
        public readonly Dictionary<int,Keys> Active=new Dictionary<int,Keys>();
        public readonly HashSet<Keys> Occupied=new HashSet<Keys>();
        public Action<int,Shortcut> BeforeRegister;
        public bool Register(int id,Shortcut shortcut){if(BeforeRegister!=null)BeforeRegister(id,shortcut);if(Occupied.Contains(shortcut.Chord)||Active.ContainsValue(shortcut.Chord))return false;Active[id]=shortcut.Chord;return true;}
        public void Unregister(int id){Active.Remove(id);}
    }
    internal static class SettingsTests
    {
        private static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
        private static Shortcut Get(Shortcut[] set,AppCommand command){return set.First(s=>s.Command==command);}
        private static void Reject(Action action){try{action();throw new Exception("Invalid shortcut accepted.");}catch(InvalidDataException){}}
        private static IEnumerable<Control> Descendants(Control root){foreach(Control child in root.Controls){yield return child;foreach(var nested in Descendants(child))yield return nested;}}
        public static void Run(Action<string,Action> test,string directory)
        {
            var previousContext=SynchronizationContext.Current;var originalTheme=UiTheme.Dark;var originalShortcuts=Shortcuts.Active;string originalStyle=UiTheme.Style;UiTheme.Style="Aftershock";UiTheme.Dark=true;
            try{
                test("Default action shortcuts are complete and unique",delegate{var set=Shortcuts.Defaults();Shortcuts.Validate(set,null);Check(set.Length==Enum.GetValues(typeof(AppCommand)).Length&&Get(set,AppCommand.Stop).Chord==Keys.F10,"Default shortcuts missing.");});
                test("Duplicate shortcuts rejected before registration",delegate{var set=Shortcuts.Defaults();Get(set,AppCommand.Stop).Key=(int)Keys.F9;Reject(delegate{Shortcuts.Validate(set,null);});});
                test("Stop cannot be unassigned",delegate{var set=Shortcuts.Defaults();Get(set,AppCommand.Stop).Key=0;Reject(delegate{Shortcuts.Validate(set,null);});});
                test("Other actions may be unassigned",delegate{var set=Shortcuts.Defaults();var record=Get(set,AppCommand.Record);record.Key=record.Modifiers=0;Shortcuts.Validate(set,null);Check(!Shortcuts.Find(set,Keys.F8).HasValue,"Unassigned key still dispatches.");});
                test("Reserved and modifier-only shortcuts are rejected",delegate{foreach(var key in new[]{Keys.ControlKey,Keys.LWin,Keys.F12}){var set=Shortcuts.Defaults();Get(set,AppCommand.Record).Key=(int)key;Reject(delegate{Shortcuts.Validate(set,null);});}});
                test("Saved macro binding conflicts are rejected",delegate{var set=Shortcuts.Defaults();Get(set,AppCommand.Record).Key=(int)Keys.D1;Get(set,AppCommand.Record).Modifiers=(int)(Keys.Control|Keys.Alt);Reject(delegate{Shortcuts.Validate(set,new[]{"test.mmacro.json"});});});
                test("Shortcut routing respects exact modifiers",delegate{var set=Shortcuts.Defaults();Get(set,AppCommand.Stop).Key=(int)Keys.Q;Get(set,AppCommand.Stop).Modifiers=(int)(Keys.Control|Keys.Shift);Check(Shortcuts.Find(set,Keys.Control|Keys.Shift|Keys.Q)==AppCommand.Stop&&!Shortcuts.Find(set,Keys.Control|Keys.Q).HasValue,"Modifiers ignored.");Check(Get(set,AppCommand.Stop).NativeModifiers==0x4006,"Native modifier flags wrong.");});
                test("Text editing keeps typing and undo while Save shortcuts remain available",delegate{Check(Shortcuts.TextEditorOwns(Keys.A)&&Shortcuts.TextEditorOwns(Keys.Control|Keys.Z)&&Shortcuts.TextEditorOwns(Keys.Delete),"Text keys were stolen.");Check(!Shortcuts.TextEditorOwns(Keys.Control|Keys.S)&&!Shortcuts.TextEditorOwns(Keys.F2),"Document shortcuts blocked in fields.");});
                test("Remapped control keys excluded while old F keys can be recorded",delegate{var set=Shortcuts.Defaults();Get(set,AppCommand.Record).Key=(int)Keys.R;Get(set,AppCommand.Record).Modifiers=(int)(Keys.Control|Keys.Alt);Check(Shortcuts.RecordingControl(set,(int)Keys.R,Keys.Control|Keys.Alt),"New control combination recorded.");Check(!Shortcuts.RecordingControl(set,(int)Keys.F8,Keys.None)&&!Shortcuts.RecordingControl(set,(int)Keys.R,Keys.None),"Ordinary keys excluded.");});
                test("Global shortcuts can swap existing keys atomically",delegate{var backend=new TestHotkeyRegistrar();using(var manager=new HotkeyManager(backend)){string error;Check(manager.TryApply(Shortcuts.Defaults(),out error),error);var set=Shortcuts.Defaults();Get(set,AppCommand.Record).Key=(int)Keys.F10;Get(set,AppCommand.Stop).Key=(int)Keys.F8;Check(manager.TryApply(set,out error),error);Check(backend.Active[1]==Keys.F10&&backend.Active[3]==Keys.F8&&backend.Active.Count==4,"Swapped registration incorrect.");}});
                test("Registration conflict restores previous working bindings",delegate{var backend=new TestHotkeyRegistrar();using(var manager=new HotkeyManager(backend)){string error;manager.TryApply(Shortcuts.Defaults(),out error);var set=Shortcuts.Defaults();Get(set,AppCommand.Stop).Key=(int)Keys.Q;Get(set,AppCommand.Stop).Modifiers=(int)Keys.Control;backend.Occupied.Add(Keys.Control|Keys.Q);Check(!manager.TryApply(set,out error)&&error.Contains("already in use"),"Conflict not reported.");Check(manager.Registered(AppCommand.Stop)&&backend.Active[3]==Keys.F10&&backend.Active.Count==4,"Working Stop not restored.");}});
                test("Failed Stop restoration reports unavailable safety control",delegate{var backend=new TestHotkeyRegistrar();using(var manager=new HotkeyManager(backend)){string error;manager.TryApply(Shortcuts.Defaults(),out error);var set=Shortcuts.Defaults();Get(set,AppCommand.Stop).Key=(int)Keys.Q;Get(set,AppCommand.Stop).Modifiers=(int)Keys.Control;backend.Occupied.Add(Keys.Control|Keys.Q);backend.BeforeRegister=delegate(int id,Shortcut s){if(s.Chord==(Keys.Control|Keys.Q))backend.Occupied.Add(Keys.F10);};Check(!manager.TryApply(set,out error)&&!manager.Registered(AppCommand.Stop)&&error.Contains("Could not restore"),"Missing safety control hidden.");}});
                test("Invalid update leaves registered keys untouched",delegate{var backend=new TestHotkeyRegistrar();using(var manager=new HotkeyManager(backend)){string error;manager.TryApply(Shortcuts.Defaults(),out error);var set=Shortcuts.Defaults();Get(set,AppCommand.Stop).Key=(int)Keys.F9;Reject(delegate{manager.TryApply(set,out error);});Check(backend.Active.Count==4&&backend.Active[3]==Keys.F10,"Validation removed working shortcuts.");}});
                test("Disposing hotkey manager releases all registered keys",delegate{var backend=new TestHotkeyRegistrar();var manager=new HotkeyManager(backend);string error;manager.TryApply(Shortcuts.Defaults(),out error);manager.Dispose();manager.Dispose();Check(backend.Active.Count==0,"Global key reservation leaked.");});
                test("Theme and customized shortcuts survive preference serialization",delegate{var prefs=new Preferences{AccentStyle="Aftershock",DarkMode=true};Get(prefs.ActionShortcuts,AppCommand.Stop).Key=(int)Keys.Q;Get(prefs.ActionShortcuts,AppCommand.Stop).Modifiers=(int)Keys.Control;var restored=Storage.Serializer().Deserialize<Preferences>(Storage.Serializer().Serialize(prefs));Shortcuts.Validate(restored.ActionShortcuts,restored.HotkeyFiles);Check(restored.DarkMode&&Get(restored.ActionShortcuts,AppCommand.Stop).Chord==(Keys.Control|Keys.Q),"Preferences changed.");});
                test("Old preferences gain default action shortcuts",delegate{var prefs=Storage.Serializer().Deserialize<Preferences>("{\"RecordMoves\":true,\"Repetitions\":3,\"Speed\":1}");Check(!prefs.DarkMode&&prefs.Repetitions==3&&Get(Shortcuts.Normalize(prefs.ActionShortcuts),AppCommand.Stop).Key==(int)Keys.F10,"Legacy preferences lost.");});
                test("Preference save atomically replaces settings and rejects invalid changes",delegate{string path=Path.Combine(directory,"settings.json");var prefs=new Preferences();prefs.SaveTo(path);prefs.DarkMode=true;prefs.SaveTo(path);string saved=File.ReadAllText(path);Check(Storage.Serializer().Deserialize<Preferences>(saved).DarkMode&&Directory.GetFiles(directory,"*.tmp").Length==0,"Preference replacement failed.");Get(prefs.ActionShortcuts,AppCommand.Stop).Key=0;Reject(delegate{prefs.SaveTo(path);});Check(File.ReadAllText(path)==saved,"Invalid update overwrote settings.");});
