                test("Repeated theme changes preserve field contents and contrast",delegate{using(var form=new Form())using(var field=new TextBox{Text="retain my settings"}){form.Controls.Add(field);for(int i=0;i<6;i++){UiTheme.Dark=i%2==0;UiTheme.Apply(form);Check(field.Text=="retain my settings"&&field.BackColor!=field.ForeColor,"Theme changed data or hid text.");}Check(!form.Visible&&!form.IsHandleCreated,"Theme activated a window.");}});
                test("Rounded button rendering leaves corners clear without showing a window",delegate{UiTheme.Dark=true;UiTheme.Style="Aftershock";using(var parent=new Form{BackColor=UiTheme.Background})using(var button=new ThemeButton{Size=new Size(96,48),Text=""})using(var bitmap=new Bitmap(96,48)){parent.Controls.Add(button);button.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));Check(bitmap.GetPixel(0,0).ToArgb()==UiTheme.Background.ToArgb()&&bitmap.GetPixel(48,24).ToArgb()==UiTheme.Field.ToArgb(),"Button reverted to a square fill.");Check(!parent.Visible&&!button.Visible,"Rendering displayed a control.");}});
                test("Aftershock accent persists independently of dark mode and old settings default to Neon",delegate{var prefs=new Preferences{AccentStyle="Aftershock",DarkMode=true};string path=Path.Combine(directory,"accent.json");prefs.SaveTo(path);var restored=Storage.Serializer().Deserialize<Preferences>(File.ReadAllText(path));Check(restored.AccentStyle=="Aftershock"&&restored.DarkMode,"Accent setting changed.");Check(Storage.Serializer().Deserialize<Preferences>("{\"Repetitions\":1,\"Speed\":1}").AccentStyle=="Neon","Older preferences have no default accent.");});
                test("Neon and Aftershock maintain readable primary and selected text",delegate{foreach(string style in new[]{"Neon","Aftershock"})foreach(bool dark in new[]{false,true}){UiTheme.Style=style;UiTheme.Dark=dark;Check(Contrast(UiTheme.Primary,UiTheme.PrimaryInk)>=4.5&&Contrast(UiTheme.Selected,UiTheme.Ink)>=4.5,"Low-contrast text in "+style);}});
