                test("Main workbench constructs hidden with settings menu and remapped hints",delegate{var prefs=new Preferences{AccentStyle="Aftershock",DarkMode=true};Get(prefs.ActionShortcuts,AppCommand.Record).Key=(int)Keys.F10;Get(prefs.ActionShortcuts,AppCommand.Stop).Key=(int)Keys.F8;using(var form=new MainForm(Samples.Nested(),null,false,false,true,prefs)){var controls=Descendants(form).ToArray();Check(controls.OfType<Button>().Any(b=>b.Text.Contains("Settings"))&&controls.OfType<Button>().Any(b=>b.AccessibleName=="Switch to light mode"&&b.Image!=null&&b.Text==""),"Settings controls missing.");Check(controls.OfType<Button>().Any(b=>b.Text=="● Record  F10")&&controls.OfType<Button>().Any(b=>b.Text=="■ Stop  F8"),"Swapped key labels wrong.");Check(!form.Visible&&!form.IsHandleCreated,"Workbench activated.");}});
