                test("Drag commit moves whole nested IF and supports exact undo redo",delegate{using(var form=new MainForm(Samples.Nested(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"drag-commit.png"));string original=Storage.Encode(form.DocumentHeadless());Check(form.DropHeadless(2,10),"Nested IF move refused.");var moved=form.DocumentHeadless();Check(moved.Steps[5].Kind==ActionKind.IfImage&&moved.Steps[9].Kind==ActionKind.EndIf,"Nested block split or wrong position.");Plan.Build(moved,directory);string after=Storage.Encode(moved);Click(Descendants(form).OfType<Button>().First(b=>b.Text=="↶ Undo"));Check(Storage.Encode(form.DocumentHeadless())==original,"Move undo not exact.");Click(Descendants(form).OfType<Button>().First(b=>b.Text=="↷ Redo"));Check(Storage.Encode(form.DocumentHeadless())==after&&!form.Visible,"Move redo not exact.");}});
                test("Rejected drag creates no history entry and leaves the macro unchanged",delegate{using(var form=new MainForm(Samples.Nested(),null,false,false,true)){string original=Storage.Encode(form.DocumentHeadless());Check(!form.DropHeadless(0,5)&&!form.DropHeadless(4,0),"Invalid drag committed.");Check(Storage.Encode(form.DocumentHeadless())==original&&!Descendants(form).OfType<Button>().First(b=>b.Text=="↶ Undo").Enabled,"Rejected move changed data/history.");}});
                test("Native drag events show a drop gap and commit without OLE or desktop input",delegate{using(var form=new MainForm(Samples.Nested(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"drag-events.png"));var list=Descendants(form).OfType<MacroListView>().Single();list.EnsureVisible(10);var data=form.BeginDragHeadless(1);var target=list.PointToScreen(new Point(20,list.Items[9].Bounds.Bottom-2));var over=new DragEventArgs(data,1,target.X,target.Y,DragDropEffects.Move,DragDropEffects.None);ControlEvent(list,"OnDragOver",over);Check(over.Effect==DragDropEffects.Move&&list.DropGap==10,"Drag cue not positioned after row. Gap="+list.DropGap+", effect="+over.Effect+", row="+list.Items[9].Bounds+", client="+list.ClientRectangle);using(var cue=new Bitmap(list.Width,list.Height)){list.DrawToBitmap(cue,new Rectangle(Point.Empty,cue.Size));Check(cue.GetPixel(list.ClientSize.Width-12,list.Items[10].Bounds.Top).ToArgb()==UiTheme.Accent.ToArgb(),"Drop line not rendered.");}ControlEvent(list,"OnDragDrop",over);Check(over.Effect==DragDropEffects.Move&&form.DocumentHeadless().Steps[9].Text.StartsWith("Outer image found"),"Native drop handler did not move the intended step.");form.EndDragHeadless();Check(list.DropGap==-1&&!form.Visible,"Drop cue not cleared.");}});
                test("External drag and Escape cancellation never modify the document",delegate{using(var form=new MainForm(Samples.Nested(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"drag-cancel.png"));var list=Descendants(form).OfType<MacroListView>().Single();string original=Storage.Encode(form.DocumentHeadless());var p=list.PointToScreen(new Point(20,60));var foreign=new DragEventArgs(new DataObject("text","foreign"),1,p.X,p.Y,DragDropEffects.Move,DragDropEffects.Move);ControlEvent(list,"OnDragOver",foreign);Check(foreign.Effect==DragDropEffects.None,"External drag accepted.");form.BeginDragHeadless(1);var cancel=new QueryContinueDragEventArgs(0,true,DragAction.Continue);ControlEvent(list,"OnQueryContinueDrag",cancel);form.EndDragHeadless();Check(cancel.Action==DragAction.Cancel&&Storage.Encode(form.DocumentHeadless())==original&&list.DropGap==-1&&!form.Visible,"Escape changed data or left drop cue.");}});
                test("Changed source snapshot rejects a stale native drop",delegate{using(var form=new MainForm(Samples.Nested(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"drag-stale.png"));var list=Descendants(form).OfType<MacroListView>().Single();var data=form.BeginDragHeadless(1);form.AddHeadless(ActionKind.Note);string changed=Storage.Encode(form.DocumentHeadless());var p=list.PointToScreen(new Point(20,list.Items[0].Bounds.Top+1));var drop=new DragEventArgs(data,1,p.X,p.Y,DragDropEffects.Move,DragDropEffects.Move);ControlEvent(list,"OnDragDrop",drop);form.EndDragHeadless();Check(drop.Effect==DragDropEffects.None&&Storage.Encode(form.DocumentHeadless())==changed,"Stale drag modified changed document.");}});
                test("Drag edge scrolling advances a hidden long list without input injection",delegate{var macro=new Macro();for(int i=0;i<80;i++)macro.Steps.Add(new Step{Kind=ActionKind.Note,Text="Row "+i});using(var form=new MainForm(macro,null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"drag-scroll.png"));var list=Descendants(form).OfType<MacroListView>().Single();int before=list.TopItem.Index;form.BeginDragHeadless(0);form.ScrollHeadless(new Point(20,list.ClientSize.Height-5));form.EndDragHeadless();Check(list.TopItem.Index>before&&!form.Visible,"Edge hover did not scroll.");}});
                test("Headless workbench defaults to Aftershock and exposes no Level column",delegate{using(var form=new MainForm(Samples.Nested(),null,false,false,true)){var list=Descendants(form).OfType<MacroListView>().Single();Check(UiTheme.Style=="Aftershock"&&UiTheme.Dark,"Headless UI uses another theme.");Check(list.Columns.Cast<ColumnHeader>().Select(c=>c.Text).SequenceEqual(new[]{"#","Action / block","Settings"}),"Level column remains or settings shifted.");Check(list.Items.Cast<ListViewItem>().All(i=>i.SubItems.Count==3&&i.Tag is StepRow),"Nesting guide metadata or columns lost.");}});
                test("Drag hit testing rejects offscreen rows then resolves scrolled targets across font sizes",delegate{foreach(float fontSize in new[]{10f,14f})using(var form=new MainForm(Samples.Nested(),null,false,false,true)){form.Size=new Size(1000,650);HeadlessUi.Render(form,Path.Combine(directory,"drag-viewport-"+fontSize+".png"));var list=Descendants(form).OfType<MacroListView>().Single();using(var font=new Font("Segoe UI",fontSize)){list.Font=font;list.EnsureVisible(0);var offscreen=new Point(20,list.Items[9].Bounds.Bottom-2);Check(!list.ClientRectangle.Contains(offscreen)&&list.GapAt(offscreen)==-1,"Offscreen destination was accepted.");list.EnsureVisible(10);var visible=new Point(20,list.Items[9].Bounds.Bottom-2);Check(list.ClientRectangle.Contains(visible)&&list.GapAt(visible)==10,"Scrolled target gap wrong at font "+fontSize+": "+visible+" client="+list.ClientRectangle);Check(!form.Visible,"Viewport test displayed a window.");}}});
                test("Headless light and dark previews render without showing forms",delegate{HeadlessUi.Previews(directory);foreach(var name in new[]{"workbench-dark.png","workbench-light.png","workbench-aftershock.png","image-editor-dark.png","shortcuts-dark.png"})using(var bitmap=new Bitmap(Path.Combine(directory,name)))Check(bitmap.Width>600&&bitmap.Height>500,"Preview missing or empty.");});
            }finally{UiTheme.Dark=originalTheme;UiTheme.Style=originalStyle;Shortcuts.Active=originalShortcuts;SynchronizationContext.SetSynchronizationContext(previousContext);}
        }
        private static void ControlEvent(Control control,string name,EventArgs args){typeof(Control).GetMethod(name,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(control,new object[]{args});}
        private static void Click(Button button){typeof(Button).GetMethod("OnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(button,new object[]{EventArgs.Empty});}
        private static double Luminance(Color color){Func<int,double> channel=delegate(int value){double v=value/255.0;return v<=0.04045?v/12.92:Math.Pow((v+0.055)/1.055,2.4);};return 0.2126*channel(color.R)+0.7152*channel(color.G)+0.0722*channel(color.B);}
        private static double Contrast(Color a,Color b){double x=Luminance(a),y=Luminance(b);return (Math.Max(x,y)+0.05)/(Math.Min(x,y)+0.05);}
    }
